mapper.insert:
INSERT INTO claim_request (
    claim_no, post_id, claimant_id, evidence, status, version, deleted
) VALUES (
    #{claimNo}, #{postId}, #{claimantId}, #{evidence}, #{status}, 0, 0
)

mapper.select:
SELECT 
FROM claim_request cr
JOIN item_post p ON p.id = cr.post_id
WHERE cr.deleted = 0
AND cr.claimant_id = #{claimantId}
AND p.publisher_id = #{publisherId}
ORDER BY cr.created_at DESC, cr.id DESC
LIMIT #{offset}, #{size}

SELECT COUNT(1)
FROM claim_request cr
JOIN item_post p ON p.id = cr.post_id
WHERE cr.deleted = 0
AND cr.claimant_id = #{claimantId}
AND p.publisher_id = #{publisherId}
